<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink, RouterView, useRoute, useRouter } from 'vue-router'
import { LayoutDashboard, BookOpen, CalendarDays, GraduationCap, LibraryBig, Users, ChartColumn, ShieldCheck, Settings2, Bell, ChevronDown, ChevronRight, LogOut, UserRound, Menu, PanelLeftClose, ClipboardList, Leaf, Layers3, Telescope, FileCheck2, CalendarRange } from 'lucide-vue-next'
import { useAuth } from '../stores/auth'
import { useWorkspace } from '../stores/workspace'
import { roleLabel, avatarText } from '../lib/format'
import { api, type Notification, type Page } from '../lib/api'
import { toast } from '../components/ToastStack.vue'

const auth = useAuth(), workspace = useWorkspace(), route = useRoute(), router = useRouter()
const menuOpen = ref(false), userMenu = ref(false), unread = ref(false), shellError = ref('')
const common = [{ to: '/', label: '工作台', icon: LayoutDashboard }]
const navigation = computed(() => [...common, ...(auth.user?.role === 'STUDENT' ? [
  { to: '/student/planning', label: '学业规划', icon: Telescope }, { to: '/student/reviews', label: '成绩复核', icon: FileCheck2 },
  { to: '/student/catalog', label: '选课中心', icon: BookOpen }, { to: '/student/timetable', label: '我的课表', icon: CalendarDays }, { to: '/student/courses', label: '我的课程', icon: LibraryBig }, { to: '/student/grades', label: '成绩与学分', icon: GraduationCap },
] : auth.user?.role === 'TEACHER' ? [
  { to: '/teacher/reviews', label: '成绩复核', icon: FileCheck2 },
  { to: '/teacher/sections', label: '授课与成绩', icon: ClipboardList },
] : [
  { to: '/admin/curricula', label: '培养方案', icon: Layers3 }, { to: '/admin/planning', label: '排课与分配', icon: CalendarRange }, { to: '/admin/reviews', label: '成绩复核', icon: FileCheck2 }, { to: '/admin/indicators', label: '指标明细', icon: ChartColumn },
  { to: '/admin/manage', label: '教学管理', icon: Settings2 }, { to: '/admin/enrollments', label: '选课与递补', icon: Users }, { to: '/admin/analytics', label: '教学分析', icon: ChartColumn }, { to: '/admin/audit', label: '操作记录', icon: ShieldCheck }, { to: '/admin/system', label: '运行与一致性', icon: Leaf, Layers3, Telescope, FileCheck2, CalendarRange },
]), { to: '/notifications', label: '消息中心', icon: Bell }])
async function loadShell() { try { shellError.value = ''; await workspace.loadTerms(); const notices = await api<Page<Notification>>('/notifications?size=20'); unread.value = notices.items.some(item => !item.readAt) } catch (e) { shellError.value = e instanceof Error ? e.message : '学期信息加载失败' } }
async function logout() { try { await auth.logout(); await router.replace('/login') } catch (e) { toast(e instanceof Error ? e.message : '退出失败，请重试。', true) } }
onMounted(loadShell)
</script>
<template><div class="app-shell" @click="userMenu = false"><a class="skip-link sr-only" href="#page-main">跳至主要内容</a><div v-if="menuOpen" class="sidebar-backdrop" @click="menuOpen = false"/><aside class="sidebar" :class="{ 'sidebar-open': menuOpen }"><RouterLink class="brand" to="/" @click="menuOpen = false"><span class="brand-mark">课</span><span>课序<small>COURSE STUDIO</small></span></RouterLink><div class="workspace-label">{{ auth.user?.role === 'STUDENT' ? '我的学习空间' : auth.user?.role === 'TEACHER' ? '教师工作空间' : '教务工作空间' }}</div><nav class="nav-list" aria-label="主要导航"><RouterLink v-for="item in navigation" :key="item.to" :to="item.to" class="nav-link" :active-class="item.to === '/' ? 'nav-root-passive' : 'router-link-active'" :exact-active-class="item.to === '/' ? 'router-link-active' : undefined" :class="{ 'router-link-active': item.to === '/' && route.path === '/' }" :aria-current="route.path === item.to ? 'page' : undefined" @click="menuOpen = false"><component :is="item.icon"/><span>{{ item.label }}</span><span v-if="item.to === '/notifications' && unread" class="nav-dot"/></RouterLink></nav><div class="sidebar-bottom"><div class="semester-card"><small>CURRENT SEMESTER</small><strong>{{ workspace.currentTerm?.name || '学期信息加载中' }}</strong><div class="row"><span>{{ workspace.currentTerm?.state === 'ACTIVE' ? '当前教学学期' : '正在查看此学期' }}</span><CalendarDays :size="13"/></div></div><p class="sidebar-footnote">把每一次选择，<br>变成有序的成长。</p></div></aside><div class="shell-content"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" :aria-expanded="menuOpen" aria-label="打开导航菜单" @click.stop="menuOpen = !menuOpen"><PanelLeftClose v-if="menuOpen" :size="20"/><Menu v-else :size="20"/></button><div class="breadcrumb"><span>教学工作台</span><ChevronRight :size="11"/><strong>{{ route.meta.title }}</strong></div></div><div class="topbar-actions"><span class="system-badge">{{ roleLabel(auth.user?.role || '') }}空间</span><RouterLink to="/notifications" class="icon-button" aria-label="查看消息"><Bell :size="18"/><span v-if="unread" class="notification-dot"/></RouterLink><div class="user-menu"><button class="user-button" :aria-expanded="userMenu" aria-haspopup="menu" @click.stop="userMenu = !userMenu"><span class="avatar">{{ avatarText(auth.user?.displayName) }}</span><span class="user-copy"><span>{{ auth.user?.displayName }}</span><small>{{ roleLabel(auth.user?.role || '') }}</small></span><ChevronDown :size="13"/></button><div v-if="userMenu" class="user-dropdown" role="menu"><p>已登录为 {{ auth.user?.username }}</p><button role="menuitem" @click="router.push('/profile')"><UserRound :size="15"/>个人信息</button><button role="menuitem" @click="logout"><LogOut :size="15"/>退出登录</button></div></div></div></header><main id="page-main" class="page-content" tabindex="-1"><div v-if="shellError" class="notice-banner notice-warning mt-20">{{ shellError }}<button class="text-button" @click="loadShell">重试加载学期</button></div><RouterView :key="route.path"/><footer class="app-footer"><span>课序 · 让教学井然有序</span><span>每一份选择，都值得认真对待。</span></footer></main></div></div></template>
